241	    static String gradeOn(List<GradeFrom> grades, LocalDate date, String otherwise) {
242	        return grades.stream().filter((g) -> g.from() == null || !g.from().isAfter(date))
243	                .max(Comparator.comparing(GradeFrom::from, Comparator.nullsFirst(Comparator.naturalOrder())))
