398	                    "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
399	                    person.name(), person.terms(), person.contact(), person.id(), person.sheetId(), person.version());
400	            if (n == 0) {
