402	            }
403	            jdbc.update("DELETE FROM person_grade WHERE person_id = ? AND sheet_id = ?", person.id(), person.sheetId());
404	            for (GradeFrom g : person.grades()) {
405	                insertGrade(person.sheetId(), person.id(), g);
406	            }
