437	    private List<Person> withGrades(String sheetId, List<Person> found) {
438	        if (found.isEmpty()) {
439	            return found;
440	        }
441	        Map<Long, List<GradeFrom>> grades = new HashMap<>();
442	        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ?", (rs) -> {
443	            grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
444	                    .add(new GradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class)));
445	        }, sheetId);
446	        Map<Long, List<Hold>> holds = new HashMap<>();
447	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id", (rs) -> {
448	            holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(new Hold(
449	                    rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
450	        }, sheetId);
451	        List<LocalDate> today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
452	                (rs, n) -> rs.getObject("today", LocalDate.class), sheetId);
453	        LocalDate on = today.isEmpty() ? LocalDate.now() : today.get(0);
454	        List<Person> people = new ArrayList<>();
455	        for (Person p : found) {
456	            List<GradeFrom> own = grades.getOrDefault(p.id(), List.of(new GradeFrom(p.grade(), null)));
457	            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(own, on, p.grade()), p.version(),
458	                    p.statementCount(), p.statedTotal(), p.statementDate(), p.retiredFrom(),
459	                    List.copyOf(holds.getOrDefault(p.id(), List.of())), List.copyOf(own), p.terms(), p.contact()));
