617	import java.io.IOException;
618	import java.io.UncheckedIOException;
619	import java.nio.charset.StandardCharsets;
620	import java.nio.file.Files;
621	import java.nio.file.Path;
622	import java.nio.file.StandardOpenOption;
623	import java.util.ArrayList;
624	import java.util.Collections;
625	import java.util.List;
626	import java.util.Locale;
627	import java.util.Set;
628	import java.util.regex.Matcher;
629	import java.util.regex.Pattern;
630	import net.officefloor.hq.app.setting.SettingRepository;
631	import org.springframework.beans.factory.annotation.Value;
632	import org.springframework.stereotype.Service;
633	
634	/**
635	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
636	 * so tests can assert side-effects by reading that file — the second test-assertion channel
637	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
638	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
639	 *
640	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
641	 * SYNC) so a test reads the record immediately.
642	 *
643	 * A change made by a user acting as a steward by delegation (one in force on the sheet's today) ends with
644	 * {@code for=<the steward who delegated>}; lines that only report figures (ROLLUP, TOTALS, ALERT) do not. A SNAPSHOT,
645	 * written as the delegated user moves the sheet's today (before it changes), is marked like a change.
646	 */
647	@Service
648	public class Audit {
649	
650	    /** The events that only report figures: never marked for a delegator. */
651	    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
652	
653	    /** A record's event, sheet and user: "EVENT sheet=<id> by=<user> ...". */
654	    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(\\S+)");
655	
656	    private final Path file;
657	
658	    private final SettingRepository settings;
659	
660	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, SettingRepository settings) {
661	        this.file = Path.of(path);
662	        this.settings = settings;
663	    }
664	
665	    /** Append one audit record. Tests assert the exact line(s) in the file. */
666	    public synchronized void record(String entry) {
667	        write(entry + forDelegator(entry));
668	    }
669	
670	    /** " for=<steward>" when the record is a change by a user acting as a steward by delegation, else "". */
671	    private String forDelegator(String entry) {
672	        Matcher head = HEAD.matcher(entry);
673	        if (!head.find() || FIGURES.contains(head.group(1))) {
674	            return "";
675	        }
676	        String by = settings.delegatorOf(head.group(2), head.group(3));
677	        return by == null ? "" : " for=" + by;
678	    }
679	
680	    private void write(String entry) {
681	        try {
682	            Path parent = file.toAbsolutePath().getParent();
683	            if (parent != null) {
684	                Files.createDirectories(parent);
685	            }
686	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
687	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
688	        } catch (IOException e) {
689	            throw new UncheckedIOException(e);
690	        }
691	    }
692	
693	    /**
694	     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only the lines about
695	     * that person: those carrying {@code name=<name>} or {@code person=<name>}, compared as names are (case and
696	     * surrounding spaces ignored). Reads the file; keeps no record of its own.
697	     */
698	    public synchronized List<String> lines(String sheetId, String name) {
699	        String wanted = name == null ? "" : name.strip().toLowerCase(Locale.ROOT);
700	        List<String> found = new ArrayList<>();
701	        try {
702	            if (!Files.exists(file)) {
703	                return found;
704	            }
705	            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
706	                Matcher head = HEAD.matcher(line);
707	                if (head.find() && head.group(2).equals(sheetId) && (wanted.isEmpty() || isAbout(line, wanted))) {
708	                    found.add(line);
709	                }
710	            }
711	        } catch (IOException e) {
712	            throw new UncheckedIOException(e);
713	        }
714	        Collections.reverse(found);
715	        return found;
716	    }
717	
718	    /** Whether the line carries name=<wanted> or person=<wanted> (wanted is lower case), the value ending the line or followed by a space. */
719	    private static boolean isAbout(String line, String wanted) {
720	        String lower = line.toLowerCase(Locale.ROOT);
721	        for (String key : List.of(" name=", " person=")) {
722	            String field = key + wanted;
723	            for (int at = lower.indexOf(field); at >= 0; at = lower.indexOf(field, at + 1)) {
724	                int end = at + field.length();
725	                if (end == lower.length() || lower.charAt(end) == ' ') {
726	                    return true;
727	                }
728	            }
729	        }
730	        return false;
731	    }
732	
733	    /** Remove the audit file. */
734	    public synchronized void clear() {
735	        try {
736	            Files.deleteIfExists(file);
737	        } catch (IOException e) {
738	            throw new UncheckedIOException(e);
739	        }
740	    }
741	}
