import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonBacking, PersonPatrons } from './PersonPatrons';

export const contributions = [
  PersonColumnHeads.fill({ order: 19.5, Component: () => <th>Patrons</th> }),
  PersonColumns.fill({ order: 19.5, Component: PersonPatrons }),
  PersonColumnHeads.fill({ order: 19.6, Component: () => <th>Backing</th> }),
  PersonColumns.fill({ order: 19.6, Component: PersonBacking }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** That the person `personId` names `patronId`, another person on the sheet, as a patron. */
export type Patron = { personId: number; patronId: number };

/** The query key for the sheet's patrons; under sheetKey, so re-loading the sheet re-reads them. */
export const patronsKey = (sheet: string) => [...sheetKey(sheet), 'patrons'] as const;

/** Every person's patrons on the sheet. */
export function usePatrons() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: patronsKey(sheet),
    queryFn: () => getJson<Patron[]>(`/api/sheets/${encodeURIComponent(sheet)}/patrons`),
    enabled: !!sheet,
  });
}

/** The ids of the person's patrons. */
export const patronIdsOf = (patrons: Patron[], personId: number) =>
  patrons.filter((p) => p.personId === personId).map((p) => p.patronId);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { usePersonError } from '../people/personError';
import { NA, total } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { patronIdsOf, patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

// A person's patrons (their names, sorted) and the select and button that name one more: anyone else on
// the sheet who is not already their patron.
export function PersonPatrons({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const ids = patronIdsOf(usePatrons().data ?? [], person.id);
  const [chosen, setChosen] = useState('');
  const [error, setError] = usePersonError(person.id, 'patron');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const names = people
    .filter((p) => ids.includes(p.id))
    .map((p) => p.name)
    .sort((a, b) => a.localeCompare(b));
  const offered = people.filter((p) => p.id !== person.id && !ids.includes(p.id));

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons?user=${encodeURIComponent(user)}`,
        { patronId },
      ),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheet) });
    },
    onError: () => setError('The patron could not be added.'),
  });

  const submit = () => {
    setError('');
    if (!chosen) {
      setError('Choose a patron.');
      return;
    }
    once(() => add.mutateAsync(Number(chosen)));
  };

  return (
    <td>
      <span data-testid="person-patrons">{names.join(', ')}</span>{' '}
      <select
        data-testid="person-patron-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          setError('');
        }}
      >
        <option value="" />
        {offered.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
          </option>
        ))}
      </select>
      <button type="button" data-testid="person-patron-add" disabled={add.isPending} onClick={submit}>
        Add patron
      </button>
      {error && <span data-testid="person-patron-error">{error}</span>}
    </td>
  );
}

/** How many days back from the sheet's today, today included, a patron's settled claim counts toward backing. */
const BACKING_DAYS = 90;

/** The first date (yyyy-MM-dd) of the backing window ending on the sheet's today. */
const backingStart = (today: string) =>
  new Date(Date.parse(`${today}T00:00:00Z`) - (BACKING_DAYS - 1) * 86_400_000).toISOString().slice(0, 10);

// A person's backing: their patrons' SETTLED claims dated within the 90 days up to and including the sheet's
// today, each at the figure frozen when it was settled, added up; 0.00 with none.
export function PersonBacking({ person }: { person: Person }) {
  const ids = patronIdsOf(usePatrons().data ?? [], person.id);
  const today = useDueRules().today;
  const claims = useClaims().data ?? [];
  const from = today === '' ? '' : backingStart(today);
  const dues = claims
    .filter((c) => ids.includes(c.personId) && c.status === 'SETTLED' && today !== '' && c.date >= from && c.date <= today)
    .map((c) => c.due ?? NA);
  return <td data-testid="person-backing">{total(dues)}</td>;
}
import { useSyncExternalStore } from 'react';
import { useCurrentSheet } from '../session/session';

// One error per person row, shared by every action on the row (a statement, a retirement, ...): the
// row shows it once, in its last cell, and the next action on the row clears it. An action whose error
// shows in its own cell (naming a patron) keeps it under its own kind; setting any error clears them all.
const errors = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The person row's error of this kind ('' when none) and the setter every action on the row uses. */
export function usePersonError(personId: number, kind = ''): [string, (message: string) => void] {
  const [sheet] = useCurrentSheet();
  const row = `${sheet}:${personId}`;
  const key = kind ? `${row}:${kind}` : row;
  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
  const setError = (message: string) => setPersonError(sheet, personId, message, kind);
  return [error, setError];
}

/** Set (or, with '', clear) a person row's error from outside the row, as a bulk action does. */
export function setPersonError(sheet: string, personId: number, message: string, kind = '') {
  const row = `${sheet}:${personId}`;
  const key = kind ? `${row}:${kind}` : row;
  for (const k of [...errors.keys()]) {
    if (k === row || k.startsWith(`${row}:`)) errors.delete(k);
  }
  if (message) errors.set(key, message);
  listeners.forEach((l) => l());
}

/** The person row's error, when there is one. */
export function PersonError({ personId }: { personId: number }) {
  const [error] = usePersonError(personId);
  return error ? <span data-testid="person-error">{error}</span> : null;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade recorded for a person, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: string; from: string | null };

/** The grade in force on the date (yyyy-MM-dd): the one recorded with the latest from-date on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** A hold on a person, from its from-date to its to-date, both inclusive (yyyy-MM-dd; null: open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether a hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to);

/**
 * The holds that apply to a person's live totals on the sheet's `today`: their own, and — from the day their
 * retirement date is reached — one covering every date, so their open and pending claims leave the totals as a
 * hold's would (settled ones, and ones a statement binds, still count).
 */
export const liveHolds = (p: { holds: Hold[]; retiredFrom: string | null }, today: string): Hold[] =>
  p.retiredFrom !== null && today !== '' && today >= p.retiredFrom ? [...p.holds, { from: null, to: null }] : p.holds;

/**
 * A person on the sheet as the store holds them; `grade` is the one in force on the sheet's today and
 * `grades` every grade recorded for them, each from its from-date; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they have any hold, `holds` each hold, oldest first: their open claims dated within one, and not bound by a
 * statement, count in no live total. `terms` is the person's own terms in days, null when they have none;
 * `contact` their contact (trimmed, lower-cased), null when they have none.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
};

/**
 * The fields the person form submits; a blank `gradeFrom` is the sheet's today, blank `terms` none of their own,
 * blank `contact` none.
 */
export type PersonInput = { name: string; grade: string; gradeFrom: string; terms: string; contact: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);

/** Whether retired people are listed; off until the toggle is turned on, and kept when a sheet is loaded. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Extra column headers of the people table: each contribution renders its own <th>. */
export const PersonColumnHeads = defineSlot('people.columnHeads');

/** Extra cells of a person's row, in the same order as PersonColumnHeads: each renders its own <td>. */
export const PersonColumns = defineSlot<{ person: Person }>('people.columns');
